def rec(slug, name_vi, name_en, name_ru, cats, lat, lon, addr, rating, review,
        ps_vi, ps_en, ps_ru, pl_vi, pl_en, pl_ru, hl_vi, hl_en, hl_ru,
        practical, sources, tags, photo=None, site=None):
    return {
        "id": f"{REGION}-{slug}", "slug": slug, "region": REGION, "country": "vietnam",
        "region_name_vi": RNAME, "federal_district": FD,
        "name_vi": name_vi, "name_ru": name_ru, "name_en": name_en,
        "categories": cats, "coordinates": {"lat": lat, "lon": lon}, "address_vi": addr,
        "rating": rating, "review_summary_vi": review,
        "presentation_short_vi": ps_vi, "presentation_short_en": ps_en, "presentation_short_ru": ps_ru,
        "presentation_long_vi": pl_vi, "presentation_long_en": pl_en, "presentation_long_ru": pl_ru,
        "highlights_vi": hl_vi, "highlights_en": hl_en, "highlights_ru": hl_ru,
        "practical": practical, "photo": photo, "photo_credit": None, "official_site": site,
        "sources": sources, "tags": tags, "status": "enriched", "last_updated": TODAY,
    }


